import Link from "next/link";
import { ArrowLeft, ArrowRight, Check, Circle, Flag, Map, ShieldCheck, Sparkles, Target } from "lucide-react";
import ConfidenceRing from "../components/ui/ConfidenceRing";

export default function NarrativeGoalPreviewScreen({ narrative, editHref = null }) { return <main className="app-surface min-h-screen overflow-x-hidden"><div className="mx-auto max-w-[393px] px-4 pb-32 pt-10">
  <Link className="mb-6 inline-flex min-h-11 items-center gap-2 text-sm font-semibold text-slate-500" href="/goals"><ArrowLeft size={18}/>Current Goal</Link>
  {editHref&&<div className="mb-4 flex justify-end"><Link className="inline-flex min-h-11 items-center rounded-xl border border-[var(--divider)] bg-[var(--surface-elevated)] px-4 text-sm font-extrabold text-[var(--primary)]" href={editHref}>Edit Goal</Link></div>}
  <section data-testid="journey-hero" className="overflow-hidden rounded-[30px] border border-amber-200/70 bg-gradient-to-br from-amber-50 via-[var(--surface-elevated)] to-emerald-50 p-5 shadow-[0_24px_64px_-34px_rgba(180,83,9,.55)] dark:border-amber-300/15 dark:from-amber-300/[.08] dark:via-white/[.06] dark:to-emerald-300/[.06]">
    <div className="flex items-start justify-between gap-4"><div className="min-w-0"><p className="text-[10px] font-black uppercase tracking-[.14em] text-amber-700 dark:text-amber-300">Goal journey</p><h1 className="mt-3 text-[30px] font-black leading-[1.08] text-slate-950">{narrative.hero.title}</h1><p className="mt-3 inline-flex rounded-full bg-emerald-100 px-3 py-1 text-xs font-black text-emerald-800 dark:bg-emerald-300/10 dark:text-emerald-300">{narrative.hero.state}</p></div><ConfidenceRing label="Confidence" size={82} value={narrative.hero.confidence}/></div>
    <p className="mt-5 text-[15px] font-semibold leading-6 text-slate-700">{narrative.hero.conclusion}</p>{narrative.hero.estimate&&<p className="mt-4 border-t border-amber-200/60 pt-3 text-xs font-bold text-slate-500">Current estimate <strong className="ml-1 text-slate-900">{narrative.hero.estimate}</strong></p>}
  </section>

  <section data-testid="journey-map" className="py-9"><SectionIntro eyebrow="The route" title="Journey map" body={narrative.journeyMap.summary??"The path behind you is longer than the path ahead."}/><div className="relative mt-6 ml-2 space-y-0 before:absolute before:bottom-6 before:left-[15px] before:top-6 before:w-[2px] before:bg-gradient-to-b before:from-emerald-400 before:via-violet-400 before:to-amber-300">{narrative.journeyMap.stops.map((stop,index)=><div className="relative grid min-h-[86px] grid-cols-[32px_1fr] gap-4" key={stop.label}><RouteDot state={stop.state}/><div className="pb-5"><p className={`text-[10px] font-black uppercase tracking-[.1em] ${stop.state==="current"?"text-violet-600":"text-slate-400"}`}>{stop.state==="current"?"You are here":stop.label}</p><p className="mt-1 text-sm font-extrabold leading-5 text-slate-900">{stop.detail}</p>{index===2&&Number.isFinite(narrative.journeyMap.progress)&&<div className="mt-2 h-1.5 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-gradient-to-r from-emerald-400 to-violet-500" style={{width:`${Math.min(100,narrative.journeyMap.progress)}%`}}/></div>}</div></div>)}</div></section>

  <section className="border-y border-[var(--divider)] py-8"><SectionIntro eyebrow="Behind you" title="Ground covered" body="These are the chapters that materially shortened the road."/><div className="mt-5 space-y-5">{narrative.groundCovered.map((item,index)=><article className="grid grid-cols-[34px_1fr] gap-3" key={item.title}><span className="grid h-8 w-8 place-items-center rounded-full bg-emerald-100 text-sm font-black text-emerald-700">{index+1}</span><div><h3 className="text-base font-black text-slate-950">{item.title}</h3><p className="mt-1 text-sm font-medium leading-6 text-slate-600">{item.body}</p></div></article>)}</div></section>

  <section className="py-8"><SectionIntro eyebrow="In front of you" title="Road ahead" body="The remaining route is physical, executable, and confirmable."/><div className="mt-5 space-y-3">{narrative.roadAhead.map((item)=><article className="rounded-2xl border border-amber-200/70 bg-amber-50/60 p-4 dark:border-amber-300/15 dark:bg-amber-300/[.05]" key={`${item.type}-${item.label}`}><p className="text-[9px] font-black uppercase tracking-[.1em] text-amber-700">{item.type}</p><h3 className="mt-1 text-sm font-black text-slate-950">{item.label}</h3><p className="mt-1 text-xs font-semibold leading-5 text-slate-600">{item.detail}</p></article>)}</div></section>

  <section data-testid="completion-criteria" className="rounded-[24px] bg-slate-950 p-5 text-white dark:bg-white/[.07]"><p className="text-[10px] font-black uppercase tracking-[.14em] text-emerald-300">The finish line</p><h2 className="mt-2 text-2xl font-black">What defines completion</h2><div className="mt-5 divide-y divide-white/10">{narrative.completionCriteria.map((item)=><div className="flex items-center justify-between gap-4 py-4 first:pt-0 last:pb-0" key={item.label}><div className="flex min-w-0 items-center gap-3">{item.status==="Achieved"?<Check className="shrink-0 text-emerald-400" size={20}/>:<Circle className="shrink-0 text-amber-300" size={18}/>}<p className="text-sm font-bold leading-5">{item.label}</p></div><p className="shrink-0 text-[10px] font-black uppercase tracking-[.08em] text-slate-400">{item.status}</p></div>)}</div></section>

  <section className="py-8"><SectionIntro eyebrow="How you finish" title="Current strategy" body={narrative.strategy.conclusion}/><div className="mt-5 grid grid-cols-2 gap-2">{narrative.strategy.pillars.map((item)=><article className="rounded-2xl bg-[var(--surface-muted)] p-3" key={item.label}><p className="text-xs font-black text-slate-900">{item.label}</p><p className="mt-1 text-[11px] font-semibold leading-4 text-slate-500">{item.detail}</p></article>)}</div><p className="mt-4 rounded-xl border-l-4 border-violet-500 bg-violet-50 p-3 text-xs font-bold leading-5 text-violet-900 dark:bg-violet-300/[.06] dark:text-violet-200">{narrative.strategy.constraint}</p></section>

  <section data-testid="evidence-turning-points" className="border-y border-[var(--divider)] py-8"><SectionIntro eyebrow="What changed the picture" title="Evidence turning points"/><div className="mt-5 space-y-6">{narrative.turningPoints.map((item)=><article key={`${item.date}-${item.label}`}><p className="text-[10px] font-black uppercase tracking-[.1em] text-violet-600">{formatDate(item.date)}</p><h3 className="mt-1 text-base font-black text-slate-950">{item.label}</h3><p className="mt-1 text-sm font-medium leading-6 text-slate-600">{item.body}</p></article>)}</div></section>

  <section className="py-8"><div className="flex items-start gap-4"><ConfidenceRing label="Confidence" size={88} value={narrative.confidence.value}/><div className="min-w-0"><p className="text-[10px] font-black uppercase tracking-[.12em] text-emerald-600">Why confidence is {narrative.confidence.label.toLowerCase()}</p><p className="mt-2 text-sm font-semibold leading-6 text-slate-700">{narrative.confidence.summary}</p></div></div><div className="mt-4 space-y-2">{narrative.confidence.reasons.map((reason)=><p className="text-xs font-bold leading-5 text-slate-600" key={reason}>✓ {reason}</p>)}</div><p className="mt-4 rounded-xl bg-amber-50 p-3 text-xs font-bold leading-5 text-amber-900 dark:bg-amber-300/[.06] dark:text-amber-200"><span className="block text-[9px] font-black uppercase tracking-[.1em]">Still watching</span>{narrative.confidence.watching}</p></section>

  <section className="rounded-[22px] border border-[var(--divider)] bg-[var(--surface-elevated)] p-4"><div className="flex items-center gap-2"><ShieldCheck size={18} className="text-sky-600"/><h2 className="text-lg font-black text-slate-950">Supporting protocols</h2></div><div className="mt-3 divide-y divide-[var(--divider)]">{narrative.protocols.map((item)=><Link className="flex min-h-12 items-center justify-between gap-3 py-3" href={item.href} key={item.name}><div><p className="text-sm font-black text-slate-900">{item.name}</p><p className="mt-0.5 text-[11px] font-semibold leading-4 text-slate-500">{item.purpose}</p></div><ArrowRight className="shrink-0 text-slate-400" size={16}/></Link>)}</div></section>

  {narrative.transition&&<section className="mt-6 rounded-[26px] border border-sky-200/70 bg-gradient-to-br from-sky-50 to-emerald-50 p-5 dark:border-sky-300/15 dark:from-sky-300/[.07] dark:to-emerald-300/[.05]"><div className="flex items-center gap-2 text-sky-700"><Flag size={18}/><p className="text-[10px] font-black uppercase tracking-[.12em]">{narrative.transition.state}</p></div><h2 className="mt-3 text-2xl font-black text-slate-950">{narrative.transition.title}</h2><p className="mt-2 text-sm font-semibold leading-6 text-slate-700">{narrative.transition.body}</p></section>}
</div></main> }

function SectionIntro({eyebrow,title,body}){return <div><p className="text-[10px] font-black uppercase tracking-[.14em] text-[var(--primary)]">{eyebrow}</p><h2 className="mt-2 text-2xl font-black leading-tight text-slate-950">{title}</h2>{body&&<p className="mt-2 text-sm font-semibold leading-6 text-slate-600">{body}</p>}</div>}
function RouteDot({state}){const style={complete:"bg-emerald-500 text-white",current:"h-8 w-8 bg-violet-600 text-white ring-4 ring-violet-100",next:"bg-amber-300 text-amber-950",destination:"bg-slate-950 text-white"}[state]??"bg-slate-200";const Icon=state==="destination"?Target:state==="current"?Map:state==="complete"?Check:Sparkles;return <span className={`relative z-10 grid h-8 w-8 place-items-center rounded-full ${style}`}><Icon size={15}/></span>}
function formatDate(value){const [year,month,day]=String(value).slice(0,10).split("-").map(Number);return new Date(year,month-1,day).toLocaleDateString("en-US",{month:"short",day:"numeric"});}
